describe('404 Page Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display 404 page when navigating to invalid URL', () => {
    // Intercept the request to the root path
    cy.intercept('GET', '/').as('rootRequest');
    cy.wait('@rootRequest');

    // Navigate to an invalid URL
    cy.visit('/invalid-page');

    // Verify 404 page is displayed
    cy.get('[data-testid="error-page"]').should('be.visible');
    cy.get('[data-testid="error-title"]').should('contain', '404');
    cy.get('[data-testid="error-message"]').should('contain', 'Page not found');

    // Verify navigation back to home is possible
    cy.get('[data-testid="back-to-home-button"]').click();
    cy.url().should('include', '/');
  });

  it('should handle edge case: navigating to non-existent subdirectory', () => {
    // Intercept the request to the root path
    cy.intercept('GET', '/').as('rootRequest');
    cy.wait('@rootRequest');

    // Navigate to a non-existent subdirectory
    cy.visit('/nonexistent-subdir/invalid-page');

    // Verify 404 page is displayed
    cy.get('[data-testid="error-page"]').should('be.visible');
    cy.get('[data-testid="error-title"]').should('contain', '404');
    cy.get('[data-testid="error-message"]').should('contain', 'Page not found');

    // Verify navigation back to home is possible
    cy.get('[data-testid="back-to-home-button"]').click();
    cy.url().should('include', '/');
  });
});
